Ext.define("bcp.view.VendorPanelViewController", {
    extend: "Ext.app.ViewController",
    alias: "controller.vendorpanel",

    updateView: function (hasVendor) {
        var model = this.getViewModel(),
            store = Ext.getStore("RequestVendors"),
            refs = this.getReferences(),
            formPanel = refs.form,
            form = formPanel.getForm(),
            rec = null;
        //reset combo no matter what
        refs.comboSharedVendors.reset();

        //if vendor data exists, load it to form
        if (hasVendor) {
            rec = store.first();
            model.set("vrecord", rec);

            // Load record model into form
            form.loadRecord(rec);

            if (this.view.readOnly) {
                refs.tb1.hide();
                refs.tb2.hide();
                bcp.util.CommonUtil.makeFormReadOnly(form, true);
            } else {
                //hide the first toolbar
                refs.tb1.hide();
                refs.tb2.show();
                refs.btnRemove.show();
                refs.form.show();
                //built-in vendors are not editable, so we hide the save button and other irrelevant fields
                if (rec.get("refVendorId") < 0) {
                    refs.btnSave.hide();
                    bcp.util.CommonUtil.makeFormReadOnly(form, true);
                    this.isBuiltInVendor(form, true);
                    //TODO: if we implement something to auto show prefilled it checklist for IT Buying Service, then we don't need the code below
                    //However, we need to have a good way to check and use proper version of prefilled checklist for different FYs
                    /*if(rec.get('refVendorId')==-99){
                        refs.note1.show();
                    }else{
                        refs.note1.hide();
                    }*/
                } else {
                    refs.btnSave.show();
                    bcp.util.CommonUtil.makeFormReadOnly(form, false);
                    this.isBuiltInVendor(form, false);
                }
            }
        } else {
            model.set("vrecord", null);
            // Load record model into form
            form.reset();

            //no vendor yet
            if (this.view.readOnly) {
                refs.tb1.hide();
                refs.tb2.hide();
                bcp.util.CommonUtil.makeFormReadOnly(form, true);
            } else {
                refs.tb1.show();
                refs.tb2.hide();
                refs.btnRemove.hide();
                refs.form.hide();
                bcp.util.CommonUtil.makeFormReadOnly(form, false);
            }
        }

        //make sure the init view is the vendor view when navigate to here
        //old existing vendors card is removed so only one card now and no need for this
        //this.showView('view');
    },

    saveRequestVendor: function (record, method) {
        //used by multiple methods to create or update request vendor data
        var model = this.getViewModel(),
            reqId = model.get("generalInfo").get("requestId"),
            store = Ext.getStore("RequestVendors"),
            me = this;

        Ext.getBody().mask("Saving, please wait...", "loading");

        var url = bcp.config.Runtime.getServerBaseUrl() + "vendors/request/" + reqId;
        var isConv = record.get("convenienceCheck");
        Ext.Ajax.request({
            url: url,
            jsonData: record.data,
            method: method,
            scope: me,
            success: function (response) {
                Ext.getBody().unmask();
                //issue 610
                var files = Ext.getStore("RequestFiles");
                files.reload();
                // reload store
                store.load(function () {
                    me.updateView(true);
                });
                //MB-395
                if (isConv) {
                    var storeItem = Ext.getStore("RequestItems");
                    storeItem.reload();
                }
            }
        });
    },

    onSelectSharedVendor: function (combo, record, eOpts) {
        var msg = "",
            cp = record.get("contactPerson"),
            email = record.get("email"),
            webUrl = record.get("webUrl"),
            phone = record.get("phone"),
            fax = record.get("fax"),
            me = this;

        msg += "Vendor Name: <b>" + record.get("vendorName") + "</b><br>";
        if (cp && cp !== "") {
            msg += "Contact Name: <b>" + cp + "</b><br>";
        }
        if (email && email !== "") {
            msg += "Email: <b>" + email + "</b><br>";
        }
        if (webUrl && webUrl !== "") {
            msg += "Web URL: <b>" + webUrl + "</b><br>";
        }
        if (phone && phone !== "") {
            msg += "Phone Number: <b>" + phone + "</b><br>";
        }
        if (fax && fax !== "") {
            msg += "Fax Number: <b>" + fax + "</b><br>";
        }

        Ext.Msg.confirm("Use this Vendor", "Would you like to use this vendor:<br><br>" + msg, function (result) {
            // User confirmed yes
            if (result == "yes") {
                me.saveRequestVendor(record, "POST");
            }
        });
    },

    addVendor: function (button, e, eOpts) {
        var refs = this.getReferences(),
            model = this.getViewModel(),
            reqId = model.get("generalInfo").get("requestId"),
            combo = refs.comboSharedVendors,
            record = combo.getSelectedRecord(),
            vname = combo.rawValue,
            me = this;

        //if a record in combo is selected and user click add, treat it the same as select
        if (record) {
            this.onSelectSharedVendor(combo, record, null);
        } else {
            //user enters a name but no match found or user didn't select, so
            //use the text entered as vendor name and create a record
            if (vname && vname.trim().length > 0) {
                //issue 609
                //check if user manually typed a vendor that is likely IT Buying Service
                //NOTE: CSP is the vendor NIST use for IT Buying Service but the vendor may change if new contract awarded to a different vendor
                var phrases = ["IT Buying", "IT Buying Service", "CSP Enterprises", "CSP Enterprises, LLC"];

                // Regular expression for "CSP" to ensure it is not part of another word
                var cspRegex = /\bCSP\b/; // \b asserts a word boundary
                var foundMatch = false;

                // Check for "CSP" with case sensitivity first
                if (cspRegex.test(vname)) {
                    foundMatch = true; // Set foundMatch to true if "CSP" is found
                } else {
                    // Loop through the phrases and check if any are present in the search string (case insensitive)
                    Ext.Array.each(phrases, function (phrase) {
                        // Use the toLowerCase() method to ignore case
                        if (vname.toLowerCase().includes(phrase.toLowerCase())) {
                            foundMatch = true; // Set foundMatch to true if a match is found
                            return false; // End the loop if a match is found
                        }
                    });
                }

                //
                if (foundMatch) {
                    Ext.Msg.confirm(
                        "Confirmation",
                        "Are you using the IT Buying Service (CSP) for this order?",
                        function (btn) {
                            if (btn === "yes") {
                                this.addItBuying();
                            } else {
                                //save the vendor that the user typed
                                record = Ext.create("bcp.model.RequestVendor", {vendorName: vname, requestId: reqId});
                                me.saveRequestVendor(record, "POST");
                            }
                        },
                        this
                    );
                } else {
                    //save the vendor that the user typed
                    record = Ext.create("bcp.model.RequestVendor", {vendorName: vname, requestId: reqId});
                    me.saveRequestVendor(record, "POST");
                }
            } else {
                bcp.util.CommonUtil.showValidationError("The [Vendor Name] cannot be empty.");
            }
        }
    },

    addGuestSpeaker: function (button, e, eOpts) {
        var model = this.getViewModel(),
            reqId = model.get("generalInfo").get("requestId"),
            me = this;

        var personWindow = this.lookupReference("personwindow");
        if (personWindow) {
            //window is already created in the main view
        } else {
            personWindow = Ext.create("widget.personasvendorwindow", {reference: "personwindow"});
            //set event listeners
            personWindow.on({
                cancelGuest: {
                    fn: function (win, data) {
                        personWindow.hide();
                        me.fireViewEvent("showbbar");
                    },
                    scope: this
                }
            });
            personWindow.on({
                saveGuest: {
                    fn: function (win, record) {
                        me.saveRequestVendor(record, "POST");
                        personWindow.hide();
                        me.fireViewEvent("showbbar");
                    },
                    scope: this
                }
            });
            //add to the parent view
            this.view.add(personWindow);
        }

        var newRecord = Ext.create("bcp.model.RequestVendor", {convenienceCheck: true, vendorId: 0, requestId: reqId});
        personWindow.lookupController().getViewModel().set("record", newRecord);

        // Show the window
        personWindow.show();
        this.fireViewEvent("hidebbar");
    },

    addItBuying: function (button, e, eOpts) {
        var model = this.getViewModel(),
            reqId = model.get("generalInfo").get("requestId"),
            record = Ext.create("bcp.model.RequestVendor", {
                vendorName: "IT Buying Service",
                vendorId: -99,
                requestId: reqId
            });
        this.saveRequestVendor(record, "POST");
    },

    addUnicor: function (button, e, eOpts) {
        var model = this.getViewModel(),
            reqId = model.get("generalInfo").get("requestId"),
            record = Ext.create("bcp.model.RequestVendor", {
                vendorName: "UNICOR",
                vendorId: -100,
                requestId: reqId
            });
        this.saveRequestVendor(record, "POST");
    },

    saveVendor: function (button, e, eOpts) {
        var refs = this.getReferences(),
            form = refs.form.getForm(),
            record = null,
            method = "PUT",
            me = this;

        // Valid
        if (form.isValid()) {
            // Update associated record with values
            form.updateRecord();
            record = form.getRecord();
            me.saveRequestVendor(record, method);
        }
    },

    remove: function (button, e, eOpts) {
        var model = this.getViewModel(),
            record = model.get("vrecord"),
            store = Ext.getStore("RequestVendors"),
            reqId = record.data.requestId,
            me = this;
        if (record) {
            var isConv = record.get("convenienceCheck");
        }

        // Ask user to confirm this action
        Ext.Msg.confirm(
            "Confirm Delete",
            "Are you sure you want to delete this vendor from the request?",
            function (result) {
                // User confirmed yes
                if (result == "yes") {
                    var url = bcp.config.Runtime.getServerBaseUrl() + "vendors/request/" + reqId;
                    Ext.Ajax.request({
                        url: url,
                        method: "DELETE",
                        scope: me,
                        success: function (response) {
                            //no vendor now
                            //issue 610
                            var files = Ext.getStore("RequestFiles");
                            files.reload();
                            //reload will set hasvendor model value
                            store.load(function () {
                                me.updateView(false);
                            });
                            //MB-395
                            //only reload item if the vendor is convience check because we added a line item for it
                            //otherwise, we don't need to reload item data
                            if (isConv) {
                                var storeItem = Ext.getStore("RequestItems");
                                storeItem.reload();
                            }
                        }
                    });
                }
            }
        );
    },

    onViewBeforeShow: function (component, eOpts) {
        var model = this.getViewModel();
        //check if vendor data exists, and update the view accordingly
        this.updateView(model.get("hasVendor"));
    },

    onViewAdded: function (component, container, pos, eOpts) {
        var model = this.getViewModel(),
            form = this.lookupReference("form");

        //set a null vendor record value in vendor model initally
        model.set("vrecord", null);

        //when view is created, determine if it's readonly or editable
        if (container.xtype == "readonlyrequest" || component.readOnly) {
            component.query("toolbar")[0].hide();
            component.query("toolbar")[1].hide();
            //made all form fields readonly
            bcp.util.CommonUtil.makeFormReadOnly(form.form, true);
        }
    },

    isBuiltInVendor: function (form, isBuiltIn) {
        Ext.suspendLayouts();
        if (isBuiltIn) {
            form.getFields().each(function (field) {
                if (field.name.indexOf("vendorName") == -1) {
                    field.setVisible(false);
                } else {
                    if (field.xtype != "hiddenfield") field.setVisible(true);
                }
            });
        } else {
            form.getFields().each(function (field) {
                if (field.name == "dfvendorName") {
                    field.setVisible(false);
                } else {
                    if (field.xtype != "hiddenfield") field.setVisible(true);
                }
            });
        }
        Ext.resumeLayouts();
    }
});
